"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["99562"],{18197(e){e.exports=JSON.parse('{"id":"FIN-071","slug":"overdraft","term":"Overdraft","also_known_as":[],"difficulty":"Beginner","definition":"An overdraft happens when you spend or withdraw more money than you have in your bank account, so the balance goes below zero.","explanation":["When an account is overdrawn, the bank is effectively lending you money to cover the shortfall. If you have 200 in your account and pay a bill of 350, your balance becomes \u2212150. You now owe the bank 150.","Some accounts come with an arranged overdraft, a pre-agreed limit up to which you can go below zero. Others allow unarranged overdrafts, which happen without prior agreement and are often much more expensive.","Overdrafts are usually costly. Banks may charge interest on the overdrawn amount, daily or monthly fees, or a fee for each transaction that takes the account below zero. In some cases, payments may simply be rejected, with a fee charged for the failed payment.","An overdraft can be a useful short-term safety net for a few days until payday, but it is a poor way to borrow over longer periods. For ongoing shortfalls, a personal loan or a cheaper credit option is usually better, and building a small cash buffer in the account helps avoid overdrafts altogether."],"note":"","total":1725,"prev":{"slug":"overconfidence-bias","term":"Overconfidence Bias"},"next":{"slug":"overdraft-protection","term":"Overdraft Protection"}}')}}]);